import fs from 'node:fs';import {PythonSession} from './packages/safe-python/src/index.ts';
const {source,cancel,throws}=JSON.parse(process.argv[1]);const controller=new AbortController();let reads=0,writes=0;
const session=new PythonSession({limits:{maxSteps:1000000,maxAllocatedBytes:16000000,maxDepth:100},hashSeed:[1n,2n],signal:controller.signal,
input:{readLine(){reads++;let line='';const byte=Buffer.alloc(1);while(fs.readSync(0,byte,0,1,null)){line+=byte.toString('utf8');if(byte[0]===10)break;}if(cancel){controller.abort();if(throws)throw Error('service cancelled');}return line;}},
output:{write(text){writes++;fs.writeSync(1,text);},flush(){}}});
const result=session.exec(source),usage=session.usage;let detail;
if(result.status==='exception'){session.globals.set('failure',result.exception);const diagnostic=session.eval('str(failure)');if(diagnostic.status==='ok')detail=diagnostic.value.primitive;}
const repeated=cancel?session.eval('1'):undefined;
fs.writeSync(2,JSON.stringify({result:result.status==='exception'?{status:result.status,detail}:result,usage,reads,writes,repeated})+'\n');
if(cancel?(result.status!=='terminated'||result.reason!=='cancelled'||repeated.status!=='terminated'||repeated.reason!=='cancelled'||reads!==1):result.status!=='ok')process.exitCode=1;

